module probe;
import bootstrap::model; import bootstrap::input; import bootstrap::parse; import bootstrap::check; import bootstrap::types; import bootstrap::lex; import bootstrap::ir; import runtime::linux;
fn mix(h:usize,v:usize)->usize{return (h*%131_usize)+%v;}
fn digest()->usize{unsafe{var h:usize=0;h=mix(h,model::slot_count as usize);h=mix(h,model::inst_count as usize);h=mix(h,model::arg_count as usize);h=mix(h,ir::labels as usize);h=mix(h,model::parameter_slot_count as usize);var i:u32=1;while i<=model::inst_count{let n:model::Inst=model::insts[i as usize];h=mix(h,n.op as usize);h=mix(h,n.dst as usize);h=mix(h,n.a as usize);h=mix(h,n.b as usize);h=mix(h,n.c as usize);h=mix(h,n.aux as usize);h=mix(h,n.bits);h=mix(h,n.span.file as usize);h=mix(h,n.span.start as usize);h=mix(h,n.span.end as usize);i=i+1_u32;}i=1;while i<=model::slot_count{let s:model::Slot=model::slots[i as usize];h=mix(h,s.ty as usize);h=mix(h,s.flags as usize);h=mix(h,s.offset);h=mix(h,s.span.file as usize);h=mix(h,s.span.start as usize);h=mix(h,s.span.end as usize);i=i+1_u32;}i=1;while i<=model::arg_count{h=mix(h,model::args[i as usize] as usize);i=i+1_u32;}return h;}}
fn cursor(d:model::Decl)->bool{unsafe{let a:model::Token=types::token;let b:model::Token=lex::next(d.file,d.end as usize);return a.file==b.file&&a.start==b.start&&a.end==b.end&&a.kind==b.kind&&a.number==b.number&&a.suffix==b.suffix;}}
pub fn run()->u32{model::reset_all();input::load("test.build");parse::collect();unsafe{
var hashes:[128]usize=[0;128];var id:u32=1;while id<=model::decl_count{if model::decls[id as usize].kind==model::DECL_FUNCTION{check::function(id);hashes[id as usize]=digest();if !cursor(model::decls[id as usize]){return 11;}}id=id+1_u32;}
id=model::decl_count;while id>0_u32{if model::decls[id as usize].kind==model::DECL_FUNCTION{check::function(id);if digest()!=hashes[id as usize] || !cursor(model::decls[id as usize]){return 12;}}id=id-1_u32;}
parse::reset(1);types::seek(1,243);let node:u32=parse::expression(0,false);types::seek(2,0);let saved:model::Token=types::token;let value:types::Constant=parse::constant_value(node,model::TYPE_U32);if value.bits!=17_usize || value.ty!=model::TYPE_U32{ return 21; }if types::token.file!=saved.file||types::token.start!=saved.start||types::token.end!=saved.end{ return 22; }if types::diagnostic.file!=1_u32||types::diagnostic.start!=243_u32{return 23;}
if linux::argc()>1_usize{let bad:u32=parse::add(model::AST_NAME,model::name("missing"),0,0,0,0,41);types::seek(2,0);let ignored:types::Constant=parse::constant_value(bad,model::TYPE_U32);return 24;}
}return 0;}

